#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int h;
    int idx;
} Element;

int cmp(const void *a, const void *b) {
    Element *ea = (Element *)a;
    Element *eb = (Element *)b;
    if (eb->h != ea->h) {
        return (eb->h > ea->h) - (eb->h < ea->h);
    }
    return ea->idx - eb->idx;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int *raw_a = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        scanf("%d", &raw_a[i]);
    }

    // Comprimir elementos adjacentes iguais
    int *a = (int *)malloc((n + 2) * sizeof(int));
    int m = 0;
    a[0] = 0;
    for (int i = 0; i < n; i++) {
        if (m == 0 || raw_a[i] != a[m]) {
            m++;
            a[m] = raw_a[i];
        }
    }
    a[m + 1] = 0;
    free(raw_a);

    Element *elems = (Element *)malloc(m * sizeof(Element));
    for (int i = 1; i <= m; i++) {
        elems[i - 1].h = a[i];
        elems[i - 1].idx = i;
    }

    qsort(elems, m, sizeof(Element), cmp);

    char *active = (char *)calloc(m + 2, sizeof(char));
    int current_comp = 0;
    int max_comp = 0;

    int i = 0;
    while (i < m) {
        int j = i;
        while (j < m && elems[j].h == elems[i].h) {
            int idx = elems[j].idx;
            active[idx] = 1;

            if (active[idx - 1] && active[idx + 1]) {
                current_comp--;
            } else if (!active[idx - 1] && !active[idx + 1]) {
                current_comp++;
            }
            j++;
        }

        if (current_comp > max_comp) {
            max_comp = current_comp;
        }

        i = j;
    }

    // O número total de pedaços é 1 (parte de baixo) + número de componentes acima do corte
    printf("%d\n", max_comp + 1);

    free(a);
    free(elems);
    free(active);

    return 0;
}
